// Generated by esquadro: do not edit. A resource's form, with shadcn/ui's
// Field: a field by its kind (or yours, from src/fields.ts), what is
// required checked before sending, the API's refusals on their fields, a
// change on the version read (If-Match), a create sent once
// (Idempotency-Key), and a question before leaving with changes unsaved.
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query"
import { useBlocker, useNavigate, useRouterState, useSearch } from "@tanstack/react-router"
import { useId, useMemo, useRef, useState } from "react"
import { fields as yours } from "@/fields.ts"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { cn } from "@/lib/utils"
import { ArrowLeft, Trash2 } from "lucide-react"
import { Checkbox } from "@/components/ui/checkbox"
import { Field, FieldError, FieldGroup, FieldLabel } from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Skeleton } from "@/components/ui/skeleton"
import { Spinner } from "@/components/ui/spinner"
import { Textarea } from "@/components/ui/textarea"
import { api } from "../api.ts"
import { resources } from "../resources.gen.ts"
import { ask } from "./confirm.tsx"
import { FileInput, isStoredFile } from "./files.tsx"
import { MoneyInput } from "./money.tsx"
import { StatusDot } from "./status.tsx"
import { describe, fieldErrors, fieldMessage } from "./errors.ts"
import { capitalize, format, t } from "./i18n.ts"
import type { FieldMeta, Rec, ResourceMeta } from "./meta.ts"
import { PageFoot, PageHeader } from "./page.tsx"
import type { Resource } from "./resource.ts"
import { BackToList, useRecord } from "./show.tsx"
import { ErrorState, FormSkeleton } from "./states.tsx"
import { toast } from "./toast.tsx"

type Values = Record<string, unknown>
const NONE = "__none"

/** Fields required and left empty, found before sending. */
class MissingFields extends Error {
  constructor(readonly fields: Record<string, string>) {
    super("missing fields")
  }
}

type InputProps = { field: FieldMeta; value: unknown; onChange: (v: unknown) => void; invalid?: boolean }

/** The input of a field, by its kind. */
export function FieldInput({ field, value, onChange, invalid }: InputProps) {
  const own = yours[field.name] ?? yours[field.kind]
  if (own?.input) return <>{own.input(value, onChange)}</>
  const str = value === null || value === undefined ? "" : String(value)
  const id = `field-${field.name}`
  switch (field.kind) {
    case "bool":
      return <Checkbox id={id} checked={Boolean(value)} onCheckedChange={(c) => onChange(c === true)} aria-invalid={invalid} />
    case "textarea":
      return <Textarea id={id} value={str} onChange={(e) => onChange(e.target.value)} aria-invalid={invalid} />
    case "enum":
      return (
        <Choice id={id} field={field} value={str} onChange={onChange} invalid={invalid}>
          {field.values?.map((v) => (
            <SelectItem key={v} value={v}>
              <span className="flex items-center gap-2">
                <StatusDot field={field} value={v} />
                {format(field, v)}
              </span>
            </SelectItem>
          ))}
        </Choice>
      )
    case "relation":
      return <RelationInput id={id} field={field} value={str} onChange={onChange} invalid={invalid} />
    case "int":
      return (
        <Input
          id={id}
          type="number"
          step="1"
          value={str}
          onChange={(e) => onChange(e.target.value === "" ? null : Number(e.target.value))}
          aria-invalid={invalid}
        />
      )
    case "decimal":
      return (
        <Input id={id} inputMode="decimal" value={str} onChange={(e) => onChange(e.target.value === "" ? null : e.target.value)} aria-invalid={invalid} />
      )
    case "file":
    case "image":
      return <FileInput id={id} field={field} value={value} onChange={onChange} invalid={invalid} />
    case "money":
      return <MoneyInput id={id} value={value} onChange={onChange} invalid={invalid} negative={field.min === undefined || field.min < 0} />
    case "date":
      return <Input id={id} type="date" value={str.slice(0, 10)} onChange={(e) => onChange(e.target.value || null)} aria-invalid={invalid} />
    case "datetime":
      return (
        <Input
          id={id}
          type="datetime-local"
          value={str ? str.slice(0, 16) : ""}
          onChange={(e) => onChange(e.target.value ? new Date(e.target.value).toISOString() : null)}
          aria-invalid={invalid}
        />
      )
  }
  return <Input id={id} value={str} onChange={(e) => onChange(e.target.value === "" ? null : e.target.value)} aria-invalid={invalid} />
}

/** A choice of values; one not required can be left empty. */
function Choice({
  id,
  field,
  value,
  onChange,
  invalid,
  children,
}: { id: string; field: FieldMeta; value: string; onChange: (v: unknown) => void; invalid?: boolean; children: React.ReactNode }) {
  return (
    <Select value={value || (field.required ? undefined : NONE)} onValueChange={(v) => onChange(v === NONE ? null : v)}>
      <SelectTrigger id={id} className="w-full" aria-invalid={invalid}>
        <SelectValue placeholder="—" />
      </SelectTrigger>
      <SelectContent position="popper">
        {!field.required && <SelectItem value={NONE}>{capitalize(t("none"))}</SelectItem>}
        {children}
      </SelectContent>
    </Select>
  )
}

/** A related record, picked from its resource's list. */
function RelationInput({ id, field, value, onChange, invalid }: InputProps & { id: string; value: string }) {
  const target = (resources as unknown as Record<string, ResourceMeta>)[field.target ?? ""]
  const options = useQuery({
    queryKey: [target?.name ?? field.target, "options"],
    queryFn: () => target.api(api as never).list({ per_page: 100, limit: 100 }),
    enabled: target !== undefined,
  })
  if (!target) return <Input id={id} value={value} onChange={(e) => onChange(e.target.value || null)} aria-invalid={invalid} />
  if (options.isPending) return <Skeleton className="h-9 w-full" />
  if (options.isError) {
    return (
      <div className="flex h-9 items-center justify-between rounded-md border border-destructive/50 px-3 text-sm text-destructive">
        {t("loadFailed")}
        <Button type="button" variant="ghost" size="sm" onClick={() => options.refetch()}>
          {t("retry")}
        </Button>
      </div>
    )
  }
  return (
    <Choice id={id} field={field} value={value} onChange={onChange} invalid={invalid}>
      {options.data?.items.map((r: Rec) => (
        <SelectItem key={r.id} value={r.id}>
          {capitalize(String(r[field.display ?? "id"] ?? r.id))}
        </SelectItem>
      ))}
    </Choice>
  )
}

function initial(fields: FieldMeta[], record?: Rec, given: Record<string, unknown> = {}): Values {
  const out: Values = {}
  for (const f of fields) {
    if (f.readOnly) continue
    // A new record takes what the URL gives (?category_id=, from a
    // category's products).
    out[f.name] = record ? record[f.name] ?? null : given[f.name] !== undefined ? given[f.name] : f.default ?? (f.kind === "bool" ? false : null)
  }
  return out
}

/** A card of the form. */
type FormSection = { title: string; description?: string; fields: FieldMeta[]; side?: boolean }

/**
 * The form's cards when the resource names none: the details (texts,
 * numbers, dates) at the left; at the right, the media (images and files)
 * and how the record is filed (choices, related records, yes or no).
 */
export function defaultSections(form: FieldMeta[]): FormSection[] {
  const media = form.filter((f) => f.kind === "image" || f.kind === "file")
  const filed = form.filter((f) => f.kind === "enum" || f.kind === "relation" || f.kind === "bool")
  const details = form.filter((f) => !media.includes(f) && !filed.includes(f))
  const out: FormSection[] = [{ title: t("details"), fields: details.length > 0 ? details : form }]
  if (details.length === 0) return out
  if (media.length > 0) out.push({ title: t("media"), fields: media, side: true })
  if (filed.length > 0) out.push({ title: t("organization"), fields: filed, side: true })
  return out
}

/** The form to create a record, or to change one (with its id). */
export function ResourceForm({ resource, id }: { resource: Resource; id?: string }) {
  const record = useRecord(resource, id)
  if (id !== undefined && record.isPending) return <FormSkeleton fields={resource.form.length} />
  if (record.isError) return <ErrorState error={record.error} onRetry={() => record.refetch()} back={<BackToList resource={resource} />} />
  return <Form resource={resource} record={record.data} />
}

function Form({ resource, record }: { resource: Resource; record?: Rec }) {
  const { meta } = resource
  const fields = resource.form.filter((f) => !f.readOnly)
  // The form's cards: the resource's sections, or one with every field.
  const sections = resource.sections ?? defaultSections(resource.form)
  // A new record starts with what the URL gives (?category_id=), or with a
  // copy of another (Duplicate).
  const given = useSearch({ strict: false }) as Record<string, unknown>
  const copy = useRouterState({ select: (s) => (s.location.state as { copy?: Record<string, unknown> }).copy })
  const [values, setValues] = useState<Values>(() => initial(fields, record, { ...copy, ...given }))
  const [errors, setErrors] = useState<Record<string, string>>({})
  // A ref, not state: the blocker reads it as it is when leaving, also
  // right after saving.
  const dirty = useRef(false)
  // One key for this form: sending it again (a double click, a retry)
  // creates the record once.
  const idempotencyKey = useMemo(() => crypto.randomUUID(), [])
  const formId = useId()
  const navigate = useNavigate()
  const queryClient = useQueryClient()
  useBlocker({
    shouldBlockFn: async () => dirty.current && !(await ask(t("unsaved"))),
    enableBeforeUnload: () => dirty.current,
  })

  const save = useMutation({
    mutationFn: async () => {
      const missing: Record<string, string> = {}
      for (const f of fields) {
        const v = values[f.name]
        if (f.required && f.kind !== "bool" && (v === null || v === undefined || v === "")) missing[f.name] = "required"
      }
      if (Object.keys(missing).length > 0) throw new MissingFields(missing)
      // What is empty is left out: the API's default on a create, and empty
      // on a change (which replaces the record).
      // A file goes as its id.
      const filled = Object.fromEntries(
        Object.entries(values)
          .filter(([, v]) => v !== null && v !== undefined && v !== "")
          .map(([k, v]) => [k, isStoredFile(v) ? v.id : v]),
      )
      if (record) return meta.api(api as never).update(record.id, filled, { ifMatch: record })
      return meta.api(api as never).create(filled, { idempotencyKey })
    },
    onSuccess: (saved: Rec) => {
      dirty.current = false
      toast(t("saved"))
      queryClient.invalidateQueries({ queryKey: [meta.name] })
      navigate({ to: `/${meta.name}/${saved.id}` as never })
    },
    onError: (e) => {
      const refused = e instanceof MissingFields ? e.fields : fieldErrors(e)
      setErrors(refused)
      const first = fields.find((f) => refused[f.name])
      if (!first) {
        toast(describe(e), "error")
        return
      }
      toast(t("fixFields"), "error")
      // The first field to fix, in view and with the cursor in it.
      requestAnimationFrame(() => {
        const input = document.getElementById(`field-${first.name}`)
        input?.scrollIntoView({ block: "center", behavior: "smooth" })
        input?.focus({ preventScroll: true })
      })
    },
  })

  return (
    <form
      id={formId}
      className="flex flex-col gap-6"
      onSubmit={(e) => {
        e.preventDefault()
        save.mutate()
      }}
    >
      <PageHeader title={record ? t("editing", { name: meta.singular }) : t("creating", { name: meta.singular })} />
      {(() => {
        const card = (section: FormSection) => (
              <Card key={section.title}>
                <CardHeader className="gap-1">
                  <CardTitle>{section.title}</CardTitle>
                  {section.description && <CardDescription>{section.description}</CardDescription>}
                </CardHeader>
                <CardContent>
                  <FieldGroup className="gap-7">
                    {section.fields
                      .filter((f) => !f.readOnly)
                      .map((f) => {
                        const error = errors[f.name]
                        const input = (
                          <FieldInput
                            field={f}
                            value={values[f.name]}
                            invalid={error !== undefined}
                            onChange={(v) => {
                              dirty.current = true
                              setErrors(({ [f.name]: _, ...rest }) => rest)
                              setValues((all) => ({ ...all, [f.name]: v }))
                            }}
                          />
                        )
                        const label = (
                          <FieldLabel htmlFor={`field-${f.name}`} className="font-semibold text-muted-foreground">
                            {f.label}
                            {f.required && f.kind !== "bool" && <span className="text-destructive">*</span>}
                          </FieldLabel>
                        )
                        return (
                          <Field
                            key={f.name}
                            orientation={f.kind === "bool" ? "horizontal" : "vertical"}
                            data-invalid={error !== undefined || undefined}
                          >
                            {f.kind === "bool" ? (
                              <>
                                {input}
                                {label}
                              </>
                            ) : (
                              <>
                                {label}
                                {input}
                              </>
                            )}
                            {error && <FieldError>{fieldMessage(f, error)}</FieldError>}
                          </Field>
                        )
                      })}
                  </FieldGroup>
                </CardContent>
              </Card>
        )
        // The main cards at the left; those of the side (an image, how a
        // record is filed) in a narrower column at the right.
        const main = sections.filter((s) => !s.side)
        const side = sections.filter((s) => s.side)
        return (
          <div className={cn("grid items-start gap-4", side.length > 0 && main.length > 0 ? "lg:grid-cols-[minmax(0,1fr)_380px]" : "max-w-[1080px]")}>
            <div className="flex min-w-0 flex-col gap-4">{(main.length > 0 ? main : side).map(card)}</div>
            {side.length > 0 && main.length > 0 && <div className="flex min-w-0 flex-col gap-4">{side.map(card)}</div>}
          </div>
        )
      })()}
      {/* The form's actions, fixed at the foot of the screen. */}
      <PageFoot>
        {/* Editing goes back to the record; creating has only its actions. */}
        {record && (
          <Button type="button" variant="ghost" onClick={() => history.back()}>
            <ArrowLeft /> {t("back")}
          </Button>
        )}
        <div className="ml-auto flex gap-2">
          {record && (record.can ?? []).includes("delete") && (
            <Button
              type="button"
              variant="destructive-outline"
              onClick={async () => {
                if (!(await ask(t("confirmDelete"), { destructive: true, description: t("cantUndo"), confirm: t("delete") }))) return
                try {
                  await meta.api(api as never).delete(record.id, { ifMatch: record })
                  dirty.current = false
                  toast(t("deleted"))
                  queryClient.invalidateQueries({ queryKey: [meta.name] })
                  navigate({ to: `/${meta.name}` as never })
                } catch (e) {
                  toast(describe(e), "error")
                }
              }}
            >
              <Trash2 /> {t("delete")}
            </Button>
          )}
          <Button type="submit" form={formId} disabled={save.isPending}>
            {save.isPending && <Spinner />}
            {t("save")}
          </Button>
        </div>
      </PageFoot>
    </form>
  )
}
